function memoize(fn, { maxSize = 100, key = (...args) => JSON.stringify(args) } = {}) {
  const cache = new Map();
  const memoized = (...args) => {
    const k = key(...args);
    if (cache.has(k)) return cache.get(k);
    const value = fn(...args);
    cache.set(k, value);
    if (cache.size > maxSize) cache.delete(cache.keys().next().value); // drop the oldest
    return value;
  };
  memoized.cache = cache;
  return memoized;
