  self.onmessage = (event) => {
    const { numbers } = event.data;
    // CPU-heavy work runs here without freezing the page
    let primes = 0;
    for (const n of numbers) {
      let isPrime = n > 1;
      for (let d = 2; d * d <= n; d++) if (n % d === 0) { isPrime = false; break; }
      if (isPrime) primes++;
