  let timer = null;
  let pendingArgs = null;
  let pendingThis = null;

  const run = (ctx, args) => {
    lastRun = Date.now();
    fn.apply(ctx, args);
  };

  function throttled(...args) {
    const now = Date.now();
    if (!lastRun && !leading) lastRun = now; // skip the leading edge
    const remaining = interval - (now - lastRun);

    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      run(this, args);
    } else if (trailing) {
      pendingArgs = args; // always keep the latest
      pendingThis = this;
      timer ??= setTimeout(() => {
        timer = null;
        run(pendingThis, pendingArgs);
      }, remaining);
    }
  }
  throttled.cancel = () => {
    clearTimeout(timer);
    timer = null;
    lastRun = 0;
  };
  return throttled;
}

