const log = [];
const offMessage = chat.on("message", (from, text) => log.push(`${from}: ${text}`));
chat.once("message", () => log.push("first message notification"));
chat.on("message", () => {
  throw new Error("bad listener");
});
chat.on("error", (err) => log.push(`error handled: ${err.message}`));

