function mergeSorted(a, b, compare = (x, y) => x - y) {
  const out = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    out.push(compare(a[i], b[j]) <= 0 ? a[i++] : b[j++]); // <= keeps it stable
