function shuffle(input, random = Math.random) {
  const arr = [...input]; // shuffle a copy
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1)); // 0..i inclusive
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

