  calls++;
  if (calls === 1) throw new TypeError("Failed to fetch"); // network blip
  if (calls === 2) return new Response("busy", { status: 503, headers: { "Retry-After": "0" } });
  return new Response(JSON.stringify({ ok: true }), { status: 200 });
};

